// The built-in Windows gamepad database (fa/platform/gamepad_hid.h). A file of its own on purpose: fa_platform is a static
// library, so this object and the embedded text it references are linked only into what calls these functions (the Windows
// backend, gamepad_win32.cpp, and the tests), and the players of the other platforms do not carry the Windows lines.
#include "embedded_gamepad_db_windows.h"  // generated by fa_embed_files() in engine/platform/CMakeLists.txt
#include "fa/platform/gamepad_hid.h"

namespace fa {

std::string_view embedded_windows_gamepad_database_text() {
    return fa::gamepad_db_windows::files().front().data;  // fa_embed_files() always emits the one file
}

const GamepadMappingDb& builtin_windows_gamepad_database() {
    static const GamepadMappingDb db = [] {
        GamepadMappingDb d;
        d.add_text(embedded_windows_gamepad_database_text(), "SDL_GameControllerDB (built in, Windows lines)");
        return d;
    }();
    return db;
}

}  // namespace fa
